file,err:=parser.ParseFile(token.NewFileSet(),name,nil,parser.ParseComments);if err!=nil{t.Fatal(err)}
for _,d:=range file.Decls { f,ok:=d.(*ast.FuncDecl);if ok && f.Name.Name=="WorkerPool" && f.Doc!=nil && strings.Contains(f.Doc.Text(),"S8合同注释 worker_pool-05"){found=true} } }
if !found {t.Fatal("required public function comment missing")} }

